protected async _show(relatedTarget?: HTMLElement): Promise<void> {
  this._isTransitioning = true
  this._onBeforeShow()

  const { modal, preventBodyScroll } = this._getShowOptions()
  this._showElement({ modal, preventBodyScroll })

  await this._queueCallback(() => {
    this._isTransitioning = false
    EventHandler.trigger(
      this._element,
      this.constructor.eventName('shown'),
      { relatedTarget }
    )
  }, this._element, this._isAnimated())
}

edits.after:
protected async _show(relatedTarget?: HTMLElement): Promise<void> {
  this._isTransitioning = true
  this._onBeforeShow()

  const { modal, preventBodyScroll } = this._getShowOptions()
  this._showElement({ modal, preventBodyScroll })

  // Yield to allow native dialog focus management to complete, then ensure
  // keyboard focus lands on the autofocus element (or dialog fallback).
  await Promise.resolve()
  const autofocus = this._element.querySelector('[autofocus]')
  if (autofocus) {
    (autofocus as HTMLElement).focus()
  } else if (this._element !== document.activeElement) {
    this._element.focus()
  }

  await this._queueCallback(() => {
    this._isTransitioning = false
    EventHandler.trigger(
      this._element,
      this.constructor.eventName('shown'),
      { relatedTarget }
    )
  }, this._element, this._isAnimated())
}
